create table precision_numeric_def (big_decimal number(10,1), big_integer number(10,1), double_primitive float(34), double_wrap float(34), float_primitive float(34), float_wrap float(34), id number(19,0) not null, primary key (id));
create table precision_numeric_set (big_decimal number(38,2), big_integer number(38,0), double_primitive float(53), double_wrap float(53), float_primitive float(24), float_wrap float(24), id number(19,0) not null, primary key (id));
create table precision_time_def (local_date date, local_time timestamp(6), offset_time timestamp(6) with time zone, sql_date date, sql_time timestamp(6), dt_instant timestamp(6) with time zone, id number(19,0) not null, java_date timestamp(6), local_date_time timestamp(6), offset_date_time timestamp(6) with time zone, sql_timestamp timestamp(6), zoned_date_time timestamp(6) with time zone, primary key (id));
create table precision_time_set (local_date date, local_time timestamp(6), offset_time timestamp(6) with time zone, sql_date date, sql_time timestamp(6), dt_instant timestamp(6) with time zone, id number(19,0) not null, java_date timestamp(6), local_date_time timestamp(6), offset_date_time timestamp(6) with time zone, sql_timestamp timestamp(6), zoned_date_time timestamp(6) with time zone, primary key (id));
